void dfs(int u, int par) {
    sz[u] = 1;
    int sumGood = 0;
    vector<int> vals;
    for (int v : adj[u]) {
        if (v == par) continue;
        dfs(v, u);
        sz[u] += sz[v];
        int g = (sz[v] >= K) ? 1 : 0;
