#include <bits/stdc++.h>
using namespace std;

static const int NEG = -1e9;

int N, K;
vector<vector<int>> g;

struct Info {
    int comp; // number of completed components (size >= K)
    int rem;  // size of the open component containing this node after cuts, capped to K
};

static inline Info better(const Info& a, const Info& b) {
    if (a.comp != b.comp) return (a.comp > b.comp ? a : b);
    return (a.rem > b.rem ? a : b);
}

static inline Info addChild(const Info& cur, const Info& child) {
    Info res;
    res.comp = cur.comp + child.comp;
    int s = cur.rem + child.rem;
    if (s >= K) {
        res.comp++;
        res.rem = 0;
    } else {
        res.rem = s;
    }
    return res;
}

vector<Info> downDP; // best result in subtree rooted at v when parent side is removed and v survives

void dfs_down(int v, int p) {
    Info cur{0, 1}; // keep v itself
    for (int to : g[v]) if (to != p) {
        dfs_down(to, v);
        cur = addChild(cur, downDP[to]);
    }
    downDP[v] = cur;
}

long long answer = 0;

// reroot DFS
void dfs_all(int v, int p, const Info& upInfo) {
    // neighbors infos when v survives and connection to that neighbor survives
    vector<int> nei;
    vector<Info> part;
    if (p != -1) {
        nei.push_back(p);
        part.push_back(upInfo);
    }
    for (int to : g[v]) if (to != p) {
        nei.push_back(to);
        part.push_back(downDP[to]);
    }

    int m = (int)part.size();

    // If path consists only of vertex v, then all incident sides become separate components.
    long long comps_if_remove_v = 0;
    for (int i = 0; i < m; ++i) {
        comps_if_remove_v += part[i].comp + (part[i].rem >= K ? 1 : 0);
    }
    answer = max(answer, comps_if_remove_v);

    // Prepare prefix/suffix merge of parts around v, for reroot and for path-through-v transitions.
    // merge sequence starts from base {0,1} including vertex v.
    vector<Info> pref(m + 1), suff(m + 1);
    pref[0] = {0, 1};
    for (int i = 0; i < m; ++i) pref[i + 1] = addChild(pref[i], part[i]);

    // suffix over reversed order but still includes v as base
    suff[m] = {0, 1};
    for (int i = m - 1; i >= 0; --i) suff[i] = addChild(suff[i + 1], part[i]);

    // For each child, compute upInfo for child
    int idx = 0;
    if (p != -1) idx = 1;
    for (int to : g[v]) if (to != p) {
        int pos = idx++;
        // merge all except part[pos]
        // Need associative fold in original order; since our combine is effectively associative for this DP,
        // we can reconstruct by iterating all except pos. Degree sum is O(N^2) worst-case if done naively.
        // Instead, use prefix over left and then append right in order.
        Info merged = pref[pos];
        for (int j = pos + 1; j < m; ++j) merged = addChild(merged, part[j]);
        dfs_all(to, v, merged);
    }

    // To account for removing a path of length >= 1 passing through v:
    // choose two different incident sides (or one side and stop at v handled above) as path directions.
    // For each side i, define value if path enters from side i and stops at v:
    // removing v disconnects all other sides into components.
    // More generally, any path through v from side a to side b removes v and both chosen sides continue recursively.
    //
    // We solve this by tree DP on directed edges:
    // bestPathFrom(v, parent-side-forbidden) is handled globally by recursion below.
    // Simpler approach: compute best path entirely in DFS using "arm" values from neighbors.
    // arm through neighbor x = best number of components obtainable in that neighbor side when path starts at v and goes into x.
    // Then removing path through v using neighbors a,b gives base from all other sides + arm[a] + arm[b].
    //
    // We'll compute arm values on the fly using a helper lambda with memoization by directed edge.
}

unordered_map<long long, long long> memoArm;

// key for directed edge (from,to)
static inline long long edgeKey(int a, int b) {
    return ( (long long)a << 32 ) ^ (unsigned int)b;
}

// Forward declaration
long long solveArm(int from, int to, const Info& fromSideInfo, int parentOfFrom);

// This helper computes best result in the component on side `to` when path starts at `from` and immediately goes to `to`,
// i.e. vertices on path continue inside that side and include `to`; edge/from side to other branches are removed.
// Return number of large components created entirely in that side after deleting some path starting at from->to.
long long armDFS(int v, int p, const Info& upInfo, int blockedFrom);

// We implement a dedicated DFS per root side with reroot-like passing; overall O(N^2) would be too much.
// Instead, use memo on directed edges with recurrence:
// arm(from->to) = max over continuing to one child nxt of to, or stopping at to.
// If stop at to: all side branches of to except from become detached components.
// If continue to nxt: all other side branches except from,nxt become detached + arm(to->nxt).
unordered_map<long long, long long> armMemo;

long long getArm(int from, int to, int pto) {
    long long key = edgeKey(from, to);
    auto it = armMemo.find(key);
    if (it != armMemo.end()) return it->second;

    // Gather contributions of branches at `to` except `from`
    vector<pair<int, Info>> branches;
    for (int x : g[to]) {
        if (x == from) continue;
        if (x == pto) continue; // impossible in tree call setup, kept harmless
    }

    // We need subtree info for each neighbor side of `to` excluding `from`.
    // For child sides use downDP[child]. For parent side relative to rooted tree unknown.
    // To avoid complex full reroot memo, root tree at 0 and use parent array + upDP arrays.
    return armMemo[key] = 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> K;
    g.assign(N, {});
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    if (K <= 0) {
        cout << 0 << '\n';
        return 0;
    }

    downDP.assign(N, {0, 0});
    dfs_down(0, -1);

    // The full optimal path DP is quite intricate.
    // However, there is an important simplification:
    // after removing any path, every remaining component is exactly one of the branches attached to some vertex of the path.
    // A component has size equal to the size of a connected side-subtree cut off by the path.
    // Thus maximizing number of components with size >= K is equivalent to maximizing count of incident sides of the path
    // whose detached side size is >= K.
    //
    // For a rooted tree, for any edge (v,to), the detached side size is simply subtree size of that side.
    // Therefore the problem becomes: choose a path maximizing the number of edges incident to the path from outside,
    // counted with multiplicity by endpoint/path vertex, whose outside-side subtree size >= K.
    //
    // Let w(v,to)=1 if the component on side `to` after cutting edge v-to and taking the side not containing the path
    // has size >= K. For a fixed path, every incident outside edge contributes independently.
    // If we root the tree, each directed edge contribution can be computed from subtree sizes / complement sizes.
    //
    // Then score(path) = sum over vertices x on path of goodSides(x) - 2*sum over internal path edges contribAlongPath,
    // which can be transformed into maximum path sum on vertex weights:
    // vertex weight = number of incident sides of size >= K after cutting that edge.
    // traversing an edge between a-b removes the two side contributions corresponding to that edge from both endpoint counts.
    //
    // Hence path score for non-empty path:
    // sum vertexWeight[x] over x on path - sum edgePenalty[e] over e on path edges,
    // where edgePenalty(a,b)=good(a->b)+good(b->a).
    //
    // This is standard maximum path sum in a tree.

    vector<int> parent(N, -1), order;
    order.reserve(N);
    parent[0] = -2;
    order.push_back(0);
    for (int i = 0; i < (int)order.size(); ++i) {
        int v = order[i];
        for (int to : g[v]) if (parent[to] == -1) {
            parent[to] = v;
            order.push_back(to);
        }
    }

    vector<int> sub(N, 1);
    for (int i = N - 1; i > 0; --i) {
        int v = order[i];
        sub[parent[v]] += sub[v];
    }

    vector<int> vertexW(N, 0);
    map<pair<int,int>, int> dirGood;
    for (int v = 0; v < N; ++v) {
        for (int to : g[v]) {
            int side;
            if (parent[to] == v) side = sub[to];
            else side = N - sub[v];
            int good = (side >= K ? 1 : 0);
            dirGood[{v,to}] = good;
            vertexW[v] += good;
        }
    }

    long long best = 0;
    function<long long(int,int)> dfsMax = [&](int v, int p) -> long long {
        long long best1 = 0, best2 = 0;
        for (int to : g[v]) if (to != p) {
            long long down = dfsMax(to, v);
            long long val = down - (dirGood[{v,to}] + dirGood[{to,v}]);
            if (val > best1) {
                best2 = best1;
                best1 = val;
            } else if (val > best2) {
                best2 = val;
            }
        }
        best = max(best, (long long)vertexW[v] + best1 + best2);
        return (long long)vertexW[v] + best1;
    };

    dfsMax(0, -1);
    cout << best << '\n';
    return 0;
}

