#define MAXN 200005

int n, K;
int adj[MAXN][2]; // since tree, store up to 2 neighbors for each node (since we root)
int *edges[MAXN];
int deg[MAXN];
int parent[MAXN];
int subsize[MAXN];
int best;

void dfs(int u, int p) {
    parent[u] = p;
    subsize[u] = 1;
    for (int i = 0; i < deg[u]; i++) {
        int v = edges[u][i];
        if (v == p) continue;
        dfs(v, u);
        subsize[u] += subsize[v];
    }
}

void solve(int u) {
    // Count how many subtrees of children (excluding parent direction) have size >= K
    int cnt = 0;
    int first = 0, second = 0; // two largest extra components from above
    for (int i = 0; i < deg[u]; i++) {
        int v = edges[u][i];
        if (v == parent[u]) {
            int upsize = n - subsize[u];
            if (upsize >= K) {
                if (upsize > first) {
                    second = first;
                    first = upsize;
                } else if (upsize > second) {
                    second = upsize;
                }
            }
        } else {
            if (subsize[v] >= K) cnt++;
            // for path going through u, we might take two branches as ends
            if (subsize[v] >= K) {
                if (subsize[v] > first) {
                    second = first;
                    first = subsize[v];
                } else if (subsize[v] > second) {
                    second = subsize[v];
                }
            }
        }
    }
    // If we make u the LCA of path, we can take two special branches as ends
    // Those branches won't be counted in cnt because they are part of path
    int cand = cnt;
    if (first && second) cand = cnt - 2; // both ends removed from cnt
    else if (first || second) cand = cnt - 1;
    if (cand > best) best = cand;

    // Recurse
    for (int i = 0; i < deg[u]; i++) {
        int v = edges[u][i];
        if (v != parent[u]) solve(v);
    }
}

int main() {
    scanf("%d %d", &n, &K);
    for (int i = 1; i <= n; i++) {
        edges[i] = malloc(sizeof(int) * 3);
        deg[i] = 0;
    }
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        edges[a][deg[a]++] = b;
        edges[b][deg[b]++] = a;
    }
    dfs(1, 0);
    best = 0;
    solve(1);
    printf("%d\n", best);
    for (int i = 1; i <= n; i++) free(edges[i]);
    return 0;
}

