#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

static int N, K;
static int *head;
static Edge *edges;
static int ecnt = 0;

static int *parent_arr, *depth_arr, *subsz;
static int *order_arr;
static int *isOnPath;

static int *compNodes;
static int compCnt;

void add_edge(int u, int v) {
    edges[ecnt].to = v;
    edges[ecnt].next = head[u];
    head[u] = ecnt++;
}

void dfs_rooted(int root) {
    int *stack = (int*)malloc((N + 5) * sizeof(int));
    int top = 0, ordsz = 0;

    parent_arr[root] = 0;
    depth_arr[root] = 0;
    stack[top++] = root;

    while (top) {
        int u = stack[--top];
        order_arr[ordsz++] = u;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (v == parent_arr[u]) continue;
            parent_arr[v] = u;
            depth_arr[v] = depth_arr[u] + 1;
            stack[top++] = v;
        }
    }

    for (int i = ordsz - 1; i >= 0; --i) {
        int u = order_arr[i];
        subsz[u] = 1;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (v == parent_arr[u]) continue;
            subsz[u] += subsz[v];
        }
    }

    free(stack);
}

int build_path(int u, int v) {
    int cnt = 0;
    while (depth_arr[u] > depth_arr[v]) {
        isOnPath[u] = 1;
        compNodes[cnt++] = u;
        u = parent_arr[u];
    }
    while (depth_arr[v] > depth_arr[u]) {
        isOnPath[v] = 1;
        compNodes[cnt++] = v;
        v = parent_arr[v];
    }
    while (u != v) {
        isOnPath[u] = 1;
        isOnPath[v] = 1;
        compNodes[cnt++] = u;
        compNodes[cnt++] = v;
        u = parent_arr[u];
        v = parent_arr[v];
    }
    isOnPath[u] = 1;
    compNodes[cnt++] = u;
    return cnt;
}

int evaluate_current_path() {
    int ans = 0;
    for (int i = 0; i < compCnt; ++i) {
        int x = compNodes[i];

        for (int e = head[x]; e != -1; e = edges[e].next) {
            int y = edges[e].to;
            if (isOnPath[y]) continue;

            int sz;
            if (parent_arr[y] == x) sz = subsz[y];
            else sz = N - subsz[x];

            if (sz >= K) ans++;
        }
    }
    return ans;
}

void clear_path_marks() {
    for (int i = 0; i < compCnt; ++i) {
        isOnPath[compNodes[i]] = 0;
    }
}

int main() {
    if (scanf("%d %d", &N, &K) != 2) return 0;

    head = (int*)malloc((N + 1) * sizeof(int));
    edges = (Edge*)malloc((2 * (N - 1) + 5) * sizeof(Edge));
    parent_arr = (int*)malloc((N + 1) * sizeof(int));
    depth_arr = (int*)malloc((N + 1) * sizeof(int));
    subsz = (int*)malloc((N + 1) * sizeof(int));
    order_arr = (int*)malloc((N + 1) * sizeof(int));
    isOnPath = (int*)calloc(N + 1, sizeof(int));
    compNodes = (int*)malloc((N + 1) * sizeof(int));

    for (int i = 1; i <= N; ++i) head[i] = -1;

    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    dfs_rooted(1);

    int best = 0;

    for (int u = 1; u <= N; ++u) {
        for (int v = u + 1; v <= N; ++v) {
            compCnt = build_path(u, v);
            int cur = evaluate_current_path();
            if (cur > best) best = cur;
            clear_path_marks();
        }
    }

    printf("%d\n", best);

    free(head);
    free(edges);
    free(parent_arr);
    free(depth_arr);
    free(subsz);
    free(order_arr);
    free(isOnPath);
    free(compNodes);

    return 0;
}

