        }

        dfs(0, -1);
        System.out.println(ans);
    }

    static int dfs(int u, int p) {
        int size = 1;
        List<Integer> childSizes = new ArrayList<>();
        for (int v : adj[u]) {
            if (v == p) continue;
            int sub = dfs(v, u);
            if (sub >= k) {
                ans++;
            } else {
                childSizes.add(sub);
            }
            size += sub;
        }

        // Try to make a path through u with two largest child components that are < k
        Collections.sort(childSizes, Collections.reverseOrder());
        int pathSize = size;
        if (childSizes.size() >= 2) {
            int best = childSizes.get(0) + childSizes.get(1) + 1;
            if (best >= k) {
                ans++; // u itself forms a component with path
                pathSize = 0;
            }
        }

        // Return the maximum size of a component attached to the path going upward
        // Only return size if it's < k, otherwise we already counted it
        return size >= k ? 0 : size;
    }
}

