public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N, K;
    static int[] head, to, next, rev;
    static int edgeCnt = 0;

    static void addEdge(int u, int v) {
        to[edgeCnt] = v; next[edgeCnt] = head[u]; head[u] = edgeCnt; edgeCnt++;
        to[edgeCnt] = u; next[edgeCnt] = head[v]; head[v] = edgeCnt; rev[edgeCnt - 1] = edgeCnt; rev[edgeCnt] = edgeCnt - 1; edgeCnt++;
    }

    static int[] parent, parentEdge, order, sub;
    static int[] goodDir; // for directed edge id e: whether component on e's direction side has size >= K
    static int[] goodCountAll;
    static long[] G; // directed edge DP
    static long ans = 0;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        K = fs.nextInt();

        head = new int[N];
        Arrays.fill(head, -1);
        to = new int[2 * (N - 1)];
        next = new int[2 * (N - 1)];
        rev = new int[2 * (N - 1)];

        for (int i = 0; i < N - 1; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            addEdge(u, v);
        }

        parent = new int[N];
        Arrays.fill(parent, -1);
        parentEdge = new int[N];
        order = new int[N];
        sub = new int[N];

        buildRootedTree(0);

        goodDir = new int[2 * (N - 1)];
        goodCountAll = new int[N];

        // subtree sizes
        for (int i = N - 1; i >= 0; i--) {
            int v = order[i];
            sub[v] = 1;
            for (int e = head[v]; e != -1; e = next[e]) {
                int u = to[e];
                if (u == parent[v]) continue;
                sub[v] += sub[u];
            }
        }

        // directed edge component sizes and goodCountAll
        for (int v = 0; v < N; v++) {
            for (int e = head[v]; e != -1; e = next[e]) {
                int u = to[e];
                int size;
                if (parent[u] == v) size = sub[u];
                else size = N - sub[v];
                goodDir[e] = (size >= K ? 1 : 0);
                goodCountAll[v] += goodDir[e];
            }
            ans = Math.max(ans, goodCountAll[v]); // single-vertex path
        }

        G = new long[2 * (N - 1)];

        // First DFS/postorder: compute G[child->parent]? Actually values from descendants up to parent.
        // For directed edge a->b, recurrence depends on incoming G[c->a] from neighbors c != b.
        // We can compute child->parent in postorder since incoming from children are known.
        for (int idx = N - 1; idx >= 0; idx--) {
            int a = order[idx];
            // top maxima among start-at-a and incoming child->a
            long best1 = goodCountAll[a];
            int bestEdge1 = -1; // incoming edge c->a represented by edge rev(e) where e is a->c? not for start
            long best2 = Long.MIN_VALUE / 4;

            for (int e = head[a]; e != -1; e = next[e]) {
                int c = to[e];
                if (parent[c] == a) {
                    long val = G[rev[e]]; // c->a
                    if (val > best1) {
                        best2 = best1;
                        best1 = val;
                        bestEdge1 = rev[e];
                    } else if (val > best2) {
                        best2 = val;
                    }
                }
            }

            if (parent[a] != -1) {
                int eab = parentEdge[a]; // a -> parent[a]
                long bestExclB = best1; // parent is not among child incomings, so fine
                G[eab] = bestExclB - goodDir[eab] + (goodCountAll[parent[a]] - goodDir[rev[eab]]);
                ans = Math.max(ans, G[eab]);
            }
        }

        // Second DFS/preorder: compute parent->child and generally all remaining directed edges.
        for (int idx = 0; idx < N; idx++) {
            int a = order[idx];

            // Build top two among start-at-a and all incoming c->a for all neighbors c
            long best1 = goodCountAll[a];
            int bestEdge1 = -1; // incoming directed edge id c->a, -1 means start at a
            long best2 = Long.MIN_VALUE / 4;

            for (int e = head[a]; e != -1; e = next[e]) {
                int c = to[e];
                long val;
                if (parent[c] == a) {
                    val = G[rev[e]]; // c->a
                } else if (parent[a] == c) {
                    val = G[rev[e]]; // c->a, now from parent to a should already be computed before preorder reaches a
                } else continue;

                if (val > best1) {
                    best2 = best1;
                    best1 = val;
                    bestEdge1 = rev[e];
                } else if (val > best2) {
                    best2 = val;
                }
            }

            for (int e = head[a]; e != -1; e = next[e]) {
                int b = to[e];
                if (parent[b] != a) continue; // compute a->b
                long bestExclB;
                int incomingFromB = rev[e]; // b->a should be excluded
                if (bestEdge1 == incomingFromB) bestExclB = best2;
                else bestExclB = best1;

                if (bestExclB < goodCountAll[a]) bestExclB = goodCountAll[a];

                G[e] = bestExclB - goodDir[e] + (goodCountAll[b] - goodDir[rev[e]]);
                ans = Math.max(ans, G[e]);
            }
        }

        System.out.println(ans);
    }

    static void buildRootedTree(int root) {
        int sz = 0;
        int[] stack = new int[N];
        stack[sz++] = root;
        parent[root] = -2;
        int ord = 0;

        while (sz > 0) {
            int v = stack[--sz];
            order[ord++] = v;
            for (int e = head[v]; e != -1; e = next[e]) {
                int u = to[e];
                if (u == parent[v]) continue;
                if (parent[u] != -1) continue;
                parent[u] = v;
                parentEdge[u] = rev[e]; // u -> parent
                stack[sz++] = u;
            }
        }
        parent[root] = -1;
    }
}
